const statementsOf = `-- name: StatementsOf :many
SELECT id, made_at, action, rule, seen, until, read_at, answer, answered_at FROM statement
WHERE account_id = $1 ORDER BY made_at DESC LIMIT 20
`

type StatementsOfRow struct {
	ID         pgtype.UUID
	MadeAt     time.Time
	Action     string
	Rule       string
	Seen       string
	Until      pgtype.Timestamptz
	ReadAt     pgtype.Timestamptz
	Answer     pgtype.Text
	AnsweredAt pgtype.Timestamptz
}

// An account's statements of reasons, the newest first.
func (q *Queries) StatementsOf(ctx context.Context, accountID pgtype.UUID) ([]StatementsOfRow, error) {
	rows, err := q.db.Query(ctx, statementsOf, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StatementsOfRow
	for rows.Next() {
		var i StatementsOfRow
		if err := rows.Scan(
			&i.ID,
			&i.MadeAt,
			&i.Action,
			&i.Rule,
			&i.Seen,
			&i.Until,
			&i.ReadAt,
			&i.Answer,
			&i.AnsweredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const talkerOf = `-- name: TalkerOf :one
SELECT a.kind, coalesce(a.owner_id, a.id)::uuid AS human, coalesce(h.born, 0)::integer AS born,
  (h.rules_at IS NOT NULL)::boolean AS rules, h.chat, h.chat_muted_until, h.rested_at, sl.name, h.appear_offline
FROM account a
JOIN account h ON h.id = coalesce(a.owner_id, a.id)
JOIN sailor sl ON sl.account_id = a.id
WHERE a.id = $1
`

type TalkerOfRow struct {
	Kind           string
	Human          pgtype.UUID
	Born           int32
	Rules          bool
	Chat           pgtype.Bool
	ChatMutedUntil pgtype.Timestamptz
	RestedAt       pgtype.Timestamptz
	Name           string
	AppearOffline  bool
}

// An account as chat needs it: its kind, its human's (itself for a
// human), and its human's month of birth, Rules of the sea, chat switch,
// mute from chat and rest, and whether they appear offline to their
// shipmates.
func (q *Queries) TalkerOf(ctx context.Context, id pgtype.UUID) (TalkerOfRow, error) {
	row := q.db.QueryRow(ctx, talkerOf, id)
	var i TalkerOfRow
	err := row.Scan(
		&i.Kind,
		&i.Human,
		&i.Born,
		&i.Rules,
		&i.Chat,
		&i.ChatMutedUntil,
		&i.RestedAt,
		&i.Name,
		&i.AppearOffline,
	)
	return i, err
}

const tiesOf = `-- name: TiesOf :many
SELECT t.kind, t.other_id, t.made_at, sl.name FROM (
  SELECT 'mute'::text AS kind, other_id, made_at FROM mute WHERE mute.account_id = $1
  UNION ALL
  SELECT 'block'::text AS kind, other_id, made_at FROM block WHERE block.account_id = $1
) t JOIN sailor sl ON sl.account_id = t.other_id
ORDER BY t.made_at DESC
`

type TiesOfRow struct {
	Kind    string
	OtherID pgtype.UUID
	MadeAt  time.Time
	Name    string
}

// An account's mutes and blocks, with the sailors' names, the newest
// first.
func (q *Queries) TiesOf(ctx context.Context, accountID pgtype.UUID) ([]TiesOfRow, error) {
	rows, err := q.db.Query(ctx, tiesOf, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TiesOfRow
	for rows.Next() {
		var i TiesOfRow
		if err := rows.Scan(
			&i.Kind,
			&i.OtherID,
			&i.MadeAt,
			&i.Name,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
